-- Aprenda se Divertindo · 100 · Simulado 3 da Trilha Policial
-- Rode depois do 99-simulado-prorrogacao.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o Simulado 3 da trilha Policial: abre no sábado, 07/11/2026, às 0h, e fecha no domingo, 08/11/2026, às 23h59.
-- 100 questões de A a E, estilo AOCP, nível mais difícil, com casos práticos, 4 horas de prova (como no edital).
-- Conhecimentos gerais (40): Português 10, Raciocínio Lógico 7, Informática 7, Atualidades 4, Igualdade Racial e de Gênero 4,
--   Medicina Legal 4, Legislação Geral 4. Específicos (60): Penal 10, Processo Penal 9, Legislação Extravagante 9,
--   Contabilidade 8, Constitucional 8, Administrativo 8, Estatística 8.
-- Gabarito equilibrado: 20 questões com cada letra (A a E), sem três letras iguais seguidas.
-- Gabarito comentado liberado na segunda, 09/11, às 0h. Rodar de novo atualiza as questões, desde que ninguém tenha começado.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Toda investigação começa com uma pergunta, mas raramente termina com a resposta que se esperava. O investigador experiente aprende cedo que a primeira versão dos fatos costuma ser a mais conveniente, não a mais verdadeira. Por isso desconfia das certezas apressadas, inclusive das próprias. Não se trata de cinismo: trata-se de método. Quem investiga precisa manter abertas as hipóteses que os fatos ainda não descartaram, ainda que uma delas pareça, à primeira vista, improvável.\n\nEssa postura exige uma virtude pouco celebrada: a paciência. Num tempo em que a sociedade cobra respostas imediatas, e em que as redes sociais condenam antes de qualquer apuração, resistir à pressa é quase um ato de coragem. O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça; serve, quando muito, à ansiedade de quem assiste. A verdade que interessa ao processo é aquela que sobrevive ao contraditório, e não a que vence o primeiro debate.", "enunciado": "Infere-se do texto que o autor considera a paciência do investigador", "opcoes": ["um traço de cinismo diante das versões apresentadas.", "uma virtude dispensável quando há provas técnicas fartas.", "um sinal de insegurança diante das próprias certezas.", "uma condição para que a apuração resista ao contraditório.", "um obstáculo à resposta que a sociedade legitimamente cobra."], "gabarito": 3, "explicacao": "O texto opõe a pressa (inquérito rápido sobre bases frágeis) à verdade 'que sobrevive ao contraditório'. A paciência é apresentada como virtude e condição de método; o autor afasta expressamente a ideia de cinismo."}, {"materia": "port", "texto_base": "Toda investigação começa com uma pergunta, mas raramente termina com a resposta que se esperava. O investigador experiente aprende cedo que a primeira versão dos fatos costuma ser a mais conveniente, não a mais verdadeira. Por isso desconfia das certezas apressadas, inclusive das próprias. Não se trata de cinismo: trata-se de método. Quem investiga precisa manter abertas as hipóteses que os fatos ainda não descartaram, ainda que uma delas pareça, à primeira vista, improvável.\n\nEssa postura exige uma virtude pouco celebrada: a paciência. Num tempo em que a sociedade cobra respostas imediatas, e em que as redes sociais condenam antes de qualquer apuração, resistir à pressa é quase um ato de coragem. O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça; serve, quando muito, à ansiedade de quem assiste. A verdade que interessa ao processo é aquela que sobrevive ao contraditório, e não a que vence o primeiro debate.", "enunciado": "No trecho “Não se trata de cinismo: trata-se de método”, os dois-pontos introduzem", "opcoes": ["uma consequência temporal da desconfiança mencionada antes.", "uma citação direta atribuída a um investigador experiente.", "uma retificação sobre a natureza da atitude descrita.", "uma condição necessária para que a desconfiança aconteça.", "uma enumeração de exemplos de condutas do investigador."], "gabarito": 2, "explicacao": "Após negar que a desconfiança seja cinismo, o autor corrige e esclarece o que ela é: método. Os dois-pontos marcam essa retificação/explicação."}, {"materia": "port", "texto_base": "Toda investigação começa com uma pergunta, mas raramente termina com a resposta que se esperava. O investigador experiente aprende cedo que a primeira versão dos fatos costuma ser a mais conveniente, não a mais verdadeira. Por isso desconfia das certezas apressadas, inclusive das próprias. Não se trata de cinismo: trata-se de método. Quem investiga precisa manter abertas as hipóteses que os fatos ainda não descartaram, ainda que uma delas pareça, à primeira vista, improvável.\n\nEssa postura exige uma virtude pouco celebrada: a paciência. Num tempo em que a sociedade cobra respostas imediatas, e em que as redes sociais condenam antes de qualquer apuração, resistir à pressa é quase um ato de coragem. O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça; serve, quando muito, à ansiedade de quem assiste. A verdade que interessa ao processo é aquela que sobrevive ao contraditório, e não a que vence o primeiro debate.", "enunciado": "Em “ainda que uma delas pareça, à primeira vista, improvável”, a expressão destacada pode ser substituída, sem alteração de sentido e com correção, por", "opcoes": ["à medida que uma delas parece, à primeira vista, improvável.", "porquanto uma delas parece, à primeira vista, improvável.", "contanto que uma delas pareça, à primeira vista, improvável.", "visto que uma delas parece, à primeira vista, improvável.", "conquanto uma delas pareça, à primeira vista, improvável."], "gabarito": 4, "explicacao": "'Ainda que' e 'conquanto' são concessivas e pedem subjuntivo. 'Porquanto' e 'visto que' são causais, 'contanto que' é condicional e 'à medida que' é proporcional."}, {"materia": "port", "texto_base": "Toda investigação começa com uma pergunta, mas raramente termina com a resposta que se esperava. O investigador experiente aprende cedo que a primeira versão dos fatos costuma ser a mais conveniente, não a mais verdadeira. Por isso desconfia das certezas apressadas, inclusive das próprias. Não se trata de cinismo: trata-se de método. Quem investiga precisa manter abertas as hipóteses que os fatos ainda não descartaram, ainda que uma delas pareça, à primeira vista, improvável.\n\nEssa postura exige uma virtude pouco celebrada: a paciência. Num tempo em que a sociedade cobra respostas imediatas, e em que as redes sociais condenam antes de qualquer apuração, resistir à pressa é quase um ato de coragem. O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça; serve, quando muito, à ansiedade de quem assiste. A verdade que interessa ao processo é aquela que sobrevive ao contraditório, e não a que vence o primeiro debate.", "enunciado": "Em “aquela que sobrevive ao contraditório”, o vocábulo “que” exerce a função sintática de", "opcoes": ["conjunção integrante da oração.", "complemento nominal de “aquela”.", "adjunto adnominal de “contraditório”.", "objeto direto do verbo “sobrevive”.", "sujeito do verbo “sobrevive”."], "gabarito": 4, "explicacao": "O pronome relativo 'que' retoma 'aquela' (a verdade) e é quem sobrevive: exerce a função de sujeito na oração adjetiva."}, {"materia": "port", "texto_base": "Toda investigação começa com uma pergunta, mas raramente termina com a resposta que se esperava. O investigador experiente aprende cedo que a primeira versão dos fatos costuma ser a mais conveniente, não a mais verdadeira. Por isso desconfia das certezas apressadas, inclusive das próprias. Não se trata de cinismo: trata-se de método. Quem investiga precisa manter abertas as hipóteses que os fatos ainda não descartaram, ainda que uma delas pareça, à primeira vista, improvável.\n\nEssa postura exige uma virtude pouco celebrada: a paciência. Num tempo em que a sociedade cobra respostas imediatas, e em que as redes sociais condenam antes de qualquer apuração, resistir à pressa é quase um ato de coragem. O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça; serve, quando muito, à ansiedade de quem assiste. A verdade que interessa ao processo é aquela que sobrevive ao contraditório, e não a que vence o primeiro debate.", "enunciado": "Assinale a alternativa em que a reescrita do trecho “O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça” mantém a correção gramatical e o sentido original.", "opcoes": ["Não serve a justiça o inquérito concluído rapidamente, porém sobre bases frágeis.", "Não serve à justiça o inquérito concluído rapidamente, mas sobre bases frágeis.", "O inquérito que conclui-se rapidamente, mas sobre bases frágeis, não serve à justiça.", "O inquérito, que se conclui rapidamente, mas sobre bases frágeis não serve à justiça.", "O inquérito concluído rapidamente sobre bases frágeis, não serve à justiça."], "gabarito": 1, "explicacao": "A primeira mantém a regência ('servir à justiça', com crase) e o sentido. Há erro na falta de crase, na ênclise após pronome relativo (que atrai próclise), na vírgula entre sujeito e verbo e na pontuação que transforma a restritiva em explicativa."}, {"materia": "port", "texto_base": "Toda investigação começa com uma pergunta, mas raramente termina com a resposta que se esperava. O investigador experiente aprende cedo que a primeira versão dos fatos costuma ser a mais conveniente, não a mais verdadeira. Por isso desconfia das certezas apressadas, inclusive das próprias. Não se trata de cinismo: trata-se de método. Quem investiga precisa manter abertas as hipóteses que os fatos ainda não descartaram, ainda que uma delas pareça, à primeira vista, improvável.\n\nEssa postura exige uma virtude pouco celebrada: a paciência. Num tempo em que a sociedade cobra respostas imediatas, e em que as redes sociais condenam antes de qualquer apuração, resistir à pressa é quase um ato de coragem. O inquérito que se conclui rapidamente, mas sobre bases frágeis, não serve à justiça; serve, quando muito, à ansiedade de quem assiste. A verdade que interessa ao processo é aquela que sobrevive ao contraditório, e não a que vence o primeiro debate.", "enunciado": "Em “Por isso desconfia das certezas apressadas, inclusive das próprias”, o termo “Por isso” estabelece com o período anterior uma relação de", "opcoes": ["concessão.", "comparação.", "condição.", "conclusão.", "finalidade."], "gabarito": 3, "explicacao": "O investigador desconfia das certezas porque aprendeu que a primeira versão é a mais conveniente: 'por isso' introduz a conclusão (consequência) do que foi dito."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que o termo “se” é partícula apassivadora.", "opcoes": ["O delegado queixou-se da demora na entrega do laudo pericial.", "Precisa-se de agentes com experiência em crimes cibernéticos.", "Investigaram-se todas as hipóteses levantadas pela equipe.", "Se a perícia confirmar o vestígio, o suspeito será indiciado.", "Trata-se de um caso complexo, com várias vítimas envolvidas."], "gabarito": 2, "explicacao": "Com verbo transitivo direto, o 'se' é apassivador e o verbo concorda com o sujeito paciente ('todas as hipóteses foram investigadas'). Nas demais: índice de indeterminação (precisa-se de, trata-se de), parte integrante do verbo (queixar-se) e conjunção condicional."}, {"materia": "port", "texto_base": null, "enunciado": "Segundo o Manual de Redação da Presidência da República, no padrão ofício, o fecho “Respeitosamente” deve ser usado", "opcoes": ["em qualquer comunicação dirigida a particulares e empresas.", "para autoridades de hierarquia superior à do remetente.", "somente quando o documento tratar de assunto sigiloso.", "apenas em comunicações dirigidas ao Presidente da República.", "para autoridades de mesma hierarquia ou de hierarquia inferior."], "gabarito": 1, "explicacao": "O Manual prevê dois fechos: 'Respeitosamente', para autoridades de hierarquia superior (inclusive o Presidente), e 'Atenciosamente', para autoridades de mesma hierarquia ou inferior."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que a colocação pronominal está de acordo com a norma-padrão.", "opcoes": ["O agente que encontrou-o deverá prestar depoimento.", "Nunca se esclareceram os motivos da fuga do preso.", "Quando lhe-perguntaram, o suspeito permaneceu calado.", "Me informaram que o laudo chegará amanhã à tarde.", "Ninguém informou-me sobre a mudança de plantão."], "gabarito": 1, "explicacao": "Palavra negativa ('nunca') atrai a próclise. Não se inicia período com pronome oblíquo átono; 'ninguém' e o pronome relativo 'que' atraem a próclise; e não há hífen na próclise ('lhe perguntaram')."}, {"materia": "port", "texto_base": null, "enunciado": "Em “O investigador, perspicaz como uma raposa, percebeu a contradição”, há a figura de linguagem denominada", "opcoes": ["hipérbole.", "metáfora.", "comparação.", "eufemismo.", "metonímia."], "gabarito": 2, "explicacao": "Há conectivo comparativo explícito ('como'), o que caracteriza a comparação ou símile. Sem o 'como' ('o investigador, uma raposa'), seria metáfora."}, {"materia": "rl", "texto_base": null, "enunciado": "Considere a proposição: “Existe um investigador que conhece todos os escrivães da delegacia”. A sua negação é:", "opcoes": ["Nenhum investigador conhece algum dos escrivães da delegacia.", "Todo investigador desconhece ao menos um escrivão da delegacia.", "Todo escrivão da delegacia é conhecido por algum dos investigadores.", "Existe um investigador que não conhece nenhum escrivão da delegacia.", "Existe um escrivão da delegacia que não conhece nenhum investigador."], "gabarito": 1, "explicacao": "Negar 'existe x tal que, para todo y, x conhece y' resulta em 'para todo x, existe y que x não conhece'. Ou seja: cada investigador desconhece ao menos um escrivão."}, {"materia": "rl", "texto_base": null, "enunciado": "Em um concurso com 120 candidatos, 70 acertaram a questão de Português, 50 acertaram a de Raciocínio Lógico e 20 acertaram as duas. Quantos candidatos não acertaram nenhuma das duas?", "opcoes": ["30", "40", "0", "20", "10"], "gabarito": 3, "explicacao": "Acertaram pelo menos uma: 70 + 50 − 20 = 100. Não acertaram nenhuma: 120 − 100 = 20."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma delegacia registrou 7 ocorrências no 1º dia de uma operação, e a cada dia seguinte foram registradas 4 a mais que no dia anterior. O total de ocorrências nos 20 primeiros dias foi", "opcoes": ["760.", "1.660.", "860.", "900.", "83."], "gabarito": 3, "explicacao": "PA com a1 = 7 e r = 4: a20 = 7 + 19 × 4 = 83. Soma = (7 + 83) × 20 ÷ 2 = 900."}, {"materia": "rl", "texto_base": null, "enunciado": "Em um pátio há viaturas (4 rodas) e motocicletas (2 rodas), num total de 30 veículos e 96 rodas. O número de viaturas é", "opcoes": ["18.", "15.", "24.", "20.", "12."], "gabarito": 0, "explicacao": "v + m = 30 e 4v + 2m = 96. Substituindo m = 30 − v: 4v + 60 − 2v = 96, então 2v = 36 e v = 18."}, {"materia": "rl", "texto_base": null, "enunciado": "Seis agentes, trabalhando 8 horas por dia, analisam um lote de documentos em 15 dias. Quatro agentes, trabalhando 6 horas por dia, no mesmo ritmo, analisarão o mesmo lote em", "opcoes": ["20 dias.", "25 dias.", "40 dias.", "22,5 dias.", "30 dias."], "gabarito": 4, "explicacao": "Total de trabalho: 6 × 8 × 15 = 720 horas-agente. Com 4 agentes a 6 h/dia: 720 ÷ 24 = 30 dias."}, {"materia": "rl", "texto_base": null, "enunciado": "Seja A uma matriz quadrada de ordem 2 com determinante igual a 5. O determinante da matriz 3A é", "opcoes": ["135.", "75.", "15.", "45.", "30."], "gabarito": 3, "explicacao": "Para matriz de ordem n, det(kA) = kⁿ × det(A). Com n = 2 e k = 3: 9 × 5 = 45."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma verba de R$ 24.000,00 será repartida entre três equipes em partes diretamente proporcionais a 2, 3 e 7. A equipe que receber a maior parte ficará com", "opcoes": ["R$ 14.000,00.", "R$ 8.000,00.", "R$ 12.000,00.", "R$ 16.800,00.", "R$ 10.500,00."], "gabarito": 0, "explicacao": "Soma das partes: 2 + 3 + 7 = 12. Cada parte vale 24.000 ÷ 12 = 2.000. A maior equipe recebe 7 × 2.000 = 14.000."}, {"materia": "inf", "texto_base": null, "enunciado": "Em uma apresentação do PowerPoint (Microsoft 365) com 40 slides, um agente quer trocar a fonte dos títulos e incluir o brasão da instituição em todos os slides de uma só vez. O recurso mais adequado é", "opcoes": ["o Painel de Animação, na guia Animações.", "o Design de Transições, na guia Transições.", "a Classificação de Slides, na guia Exibir.", "a Duplicação de Slides, na guia Página Inicial.", "o Slide Mestre, na guia Exibir."], "gabarito": 4, "explicacao": "O Slide Mestre controla a formatação e os elementos comuns de todos os slides. Uma alteração nele se reflete em todos os slides baseados nos seus layouts."}, {"materia": "inf", "texto_base": null, "enunciado": "No Word (Microsoft 365), um escrivão precisa que apenas a página 5 de um relatório de 10 páginas fique na orientação paisagem. Para isso, deve", "opcoes": ["selecionar o texto da página e aplicar orientação paisagem ao parágrafo.", "salvar a página como documento separado, pois o Word não admite essa mistura.", "inserir quebras de página antes e depois e mudar a orientação do documento.", "inserir quebras de seção antes e depois da página e mudar só aquela seção.", "criar um estilo de título com orientação paisagem e aplicá-lo à página."], "gabarito": 3, "explicacao": "A orientação é configuração de seção. Com quebras de seção, cada seção pode ter orientação, margens e cabeçalhos próprios. A quebra de página não cria nova seção."}, {"materia": "inf", "texto_base": null, "enunciado": "No Excel, a célula A1 contém o texto SSA-2026-0457. A fórmula =ESQUERDA(A1;3) retorna", "opcoes": ["SSA-", "#VALOR!", "457", "SSA", "2026"], "gabarito": 3, "explicacao": "ESQUERDA retorna o número indicado de caracteres a partir do início do texto: os 3 primeiros, 'SSA'."}, {"materia": "inf", "texto_base": null, "enunciado": "No Excel, as células A1, A2 e A3 contêm, respectivamente, 10, o texto “pendente” e 20. A fórmula =SOMA(A1:A3)/CONT.NÚM(A1:A3) retorna", "opcoes": ["15", "7,5", "10", "30", "#VALOR!"], "gabarito": 0, "explicacao": "SOMA ignora o texto: 10 + 20 = 30. CONT.NÚM conta só células com números: 2. Resultado: 30 ÷ 2 = 15."}, {"materia": "inf", "texto_base": null, "enunciado": "Sobre a deep web e a dark web, é correto afirmar que", "opcoes": ["a deep web é ilegal e reúne apenas conteúdos ligados a atividades criminosas.", "a dark web é indexada pelos buscadores comuns, como o Google e o Bing.", "a deep web é a parte da internet acessada exclusivamente pelo navegador Tor.", "a dark web é parte da deep web e exige softwares específicos, como o Tor.", "a deep web e a dark web são nomes diferentes para o mesmo conjunto de sites."], "gabarito": 3, "explicacao": "Deep web é o conteúdo não indexado pelos buscadores (como e-mails, sistemas internos e bancos de dados) e é majoritariamente legítima. A dark web é uma pequena parte dela, que exige redes e softwares específicos, como o Tor."}, {"materia": "inf", "texto_base": null, "enunciado": "Um delegado assina digitalmente um ofício e o envia ao Ministério Público. Na assinatura digital baseada em criptografia assimétrica,", "opcoes": ["o remetente e o destinatário usam a mesma chave secreta para assinar e conferir.", "o remetente assina com a chave pública do destinatário, que confere com a privada.", "o remetente assina com sua chave pública, e o destinatário confere com a privada.", "o remetente assina com a chave privada do destinatário, obtida na certificadora.", "o remetente assina com sua chave privada, e o destinatário confere com a pública."], "gabarito": 4, "explicacao": "Na assinatura digital, usa-se a chave privada do remetente para assinar e a chave pública dele para verificar. Isso garante autenticidade, integridade e não repúdio, mas não sigilo."}, {"materia": "inf", "texto_base": null, "enunciado": "No Windows 11, um programa travou e não responde. Para abrir diretamente o Gerenciador de Tarefas e encerrá-lo, o usuário pode pressionar", "opcoes": ["Ctrl + Shift + Esc", "Ctrl + Alt + Tab", "Alt + F4 + Esc", "Windows + Shift + S", "Windows + Ctrl + D"], "gabarito": 0, "explicacao": "Ctrl + Shift + Esc abre o Gerenciador de Tarefas diretamente. Windows + Shift + S abre a captura de tela, e Windows + Ctrl + D cria uma nova área de trabalho virtual."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "Em julho de 2025, o Brasil sediou a cúpula de chefes de Estado de um bloco de países emergentes, realizada na cidade do Rio de Janeiro. Trata-se do", "opcoes": ["G7.", "BRICS.", "G20.", "OCDE.", "Mercosul."], "gabarito": 1, "explicacao": "A cúpula do BRICS de 2025 foi realizada no Rio de Janeiro, sob a presidência brasileira do bloco. O Brasil havia sediado a cúpula do G20 em 2024."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "Em 2025, os Estados Unidos anunciaram tarifas de importação de 50% sobre diversos produtos brasileiros. Essa medida ficou conhecida no Brasil como", "opcoes": ["taxa das blusinhas.", "lei do cão.", "tarifaço.", "bloqueio comercial total.", "embargo do Mercosul."], "gabarito": 2, "explicacao": "O chamado 'tarifaço' entrou em vigor em agosto de 2025, com exceções para alguns produtos, e gerou negociações e medidas de apoio aos exportadores brasileiros."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "Em maio de 2025, após a morte do papa Francisco, o conclave elegeu como novo pontífice o cardeal norte-americano Robert Prevost, que adotou o nome de", "opcoes": ["Leão XIV.", "Francisco II.", "João XXIV.", "Pio XIII.", "Bento XVII."], "gabarito": 0, "explicacao": "Robert Prevost foi eleito em maio de 2025 e escolheu o nome Leão XIV. É o primeiro papa nascido nos Estados Unidos."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "Na reforma tributária do consumo, o ano de 2026 funciona como período de teste, com cobrança simbólica da CBS e do IBS. Nesse ano, as alíquotas de teste são de", "opcoes": ["9% para a CBS e 1% para o IBS.", "0,1% para a CBS e 0,9% para o IBS.", "1% para a CBS e 0,9% para o IBS.", "27% somando a CBS e o IBS.", "0,9% para a CBS e 0,1% para o IBS."], "gabarito": 4, "explicacao": "Em 2026, há a alíquota de teste de 0,9% de CBS e 0,1% de IBS, que pode ser compensada com outros tributos. A substituição gradual de PIS, Cofins, ICMS e ISS vai até 2033."}, {"materia": "igual", "texto_base": null, "enunciado": "Pela Lei 2.889/1956, comete genocídio quem, com a intenção de destruir, no todo ou em parte, um grupo, mata membros desse grupo. NÃO está entre os grupos protegidos por essa lei o grupo", "opcoes": ["racial.", "étnico.", "religioso.", "nacional.", "político."], "gabarito": 4, "explicacao": "O art. 1º da Lei 2.889/1956 protege grupos nacionais, étnicos, raciais ou religiosos, como a Convenção da ONU de 1948. Grupos políticos não foram incluídos."}, {"materia": "igual", "texto_base": null, "enunciado": "Em uma confraternização, um homem faz “piadas” que ofendem colegas negros em razão da cor da pele, sob o pretexto de ser apenas brincadeira. Pela Lei 7.716/1989, após a Lei 14.532/2023, o contexto de descontração", "opcoes": ["aumenta a pena de 1/3 até a metade.", "afasta o crime, pois não há intenção de ofender.", "exige representação da vítima para o início da ação.", "transforma o fato em contravenção penal de preconceito.", "reduz a pena de 1/3, por ausência de dolo específico."], "gabarito": 0, "explicacao": "O art. 20-A da Lei 7.716/1989 prevê aumento de pena de 1/3 até a metade quando os crimes ocorrem em contexto ou com intuito de descontração, diversão ou recreação, o chamado racismo recreativo."}, {"materia": "igual", "texto_base": null, "enunciado": "Entre os princípios que regem a República Federativa do Brasil em suas relações internacionais, a Constituição Federal (art. 4º) prevê expressamente o", "opcoes": ["direito de asilo só a vítimas de racismo.", "apoio militar a povos em conflito racial.", "repúdio ao terrorismo e ao racismo.", "dever de intervir em Estados racistas.", "bloqueio econômico a países autoritários."], "gabarito": 2, "explicacao": "Art. 4º, VIII, da CF: repúdio ao terrorismo e ao racismo. O mesmo artigo prevê não intervenção, prevalência dos direitos humanos e concessão de asilo político, sem restringi-lo a vítimas de racismo."}, {"materia": "igual", "texto_base": null, "enunciado": "A Lei 7.437/1985 (Lei Caó) alterou a Lei Afonso Arinos para incluir entre as contravenções penais a prática de atos resultantes de preconceito de", "opcoes": ["renda, profissão ou escolaridade.", "orientação política ou ideológica.", "nacionalidade, apenas, no trabalho.", "raça, cor, sexo ou estado civil.", "religião, idade ou classe social."], "gabarito": 3, "explicacao": "A Lei Caó deu nova redação à Lei 1.390/1951, passando a punir como contravenção o preconceito de raça, cor, sexo ou estado civil. Pouco depois, a Lei 7.716/1989 tratou como crime o preconceito de raça e cor."}, {"materia": "ml", "texto_base": null, "enunciado": "Pai e filho morrem no mesmo acidente de carro, e não é possível determinar qual deles morreu primeiro. Do ponto de vista médico-legal e civil, aplica-se a", "opcoes": ["premoriência do mais novo, por ser herdeiro.", "cronotanatognose, que define a ordem pela idade.", "comoriência, presumindo-se as mortes simultâneas.", "exumação obrigatória para apurar a ordem das mortes.", "premoriência do mais velho, por ser mais frágil."], "gabarito": 2, "explicacao": "Art. 8º do Código Civil: se não se puder averiguar se algum dos falecidos precedeu aos outros, presumem-se simultaneamente mortos (comoriência). Assim, um não herda do outro."}, {"materia": "ml", "texto_base": null, "enunciado": "Uma vítima apresenta ferida produzida por golpe de machado, com bordas irregulares e lesão óssea subjacente. O instrumento e a ferida classificam-se como", "opcoes": ["cortante, com ferida incisa de bordas regulares.", "cortocontundente, com ferida cortocontusa.", "perfurante, com ferida punctória de pequeno diâmetro.", "perfurocortante, com ferida perfuroincisa.", "perfurocontundente, com ferida típica de projétil."], "gabarito": 1, "explicacao": "Machado, facão e foice agem por gume e peso: são cortocontundentes e produzem feridas cortocontusas. Faca é perfurocortante, navalha é cortante, agulha é perfurante e projétil é perfurocontundente."}, {"materia": "ml", "texto_base": null, "enunciado": "No exame de um cadáver, o perito encontra manchas de hipóstase (livores) tanto no dorso quanto na face anterior do corpo. Esse achado sugere que", "opcoes": ["o corpo foi mudado de posição antes da fixação dos livores.", "a vítima morreu por afogamento em água doce e corrente.", "o corpo permaneceu sempre na mesma posição após a morte.", "a morte ocorreu há mais de 72 horas, com putrefação avançada.", "a morte foi causada por intoxicação por monóxido de carbono."], "gabarito": 0, "explicacao": "Os livores se formam nas partes mais baixas e fixam-se em cerca de 8 a 12 horas. Livores em regiões opostas indicam mudança de posição do corpo antes da fixação completa."}, {"materia": "ml", "texto_base": null, "enunciado": "Um corpo retirado de um rio apresenta, junto às narinas e à boca, espuma branca, fina e persistente (cogumelo de espuma). Esse achado indica", "opcoes": ["que o corpo está em fase avançada de putrefação.", "que houve intoxicação por álcool antes da morte.", "que o corpo foi lançado na água já sem vida.", "que a vítima respirava ao entrar na água.", "que a morte ocorreu por estrangulamento prévio."], "gabarito": 3, "explicacao": "O cogumelo de espuma resulta da mistura de ar, água e muco nas vias aéreas durante a respiração. É sinal de reação vital, típico do afogamento em vida."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Um investigador de polícia, bacharel em Direito e aprovado no Exame de Ordem, pretende advogar nas horas vagas. Pelo Estatuto da Advocacia (Lei 8.906/1994),", "opcoes": ["pode, desde que obtenha autorização do chefe da instituição.", "pode, desde que não atue em processos criminais da sua comarca.", "não pode, pois o cargo policial é incompatível com a advocacia.", "pode, desde que não atue contra a Fazenda Pública que o remunera.", "pode, pois o impedimento só alcança delegados de polícia."], "gabarito": 2, "explicacao": "Art. 28, V: a advocacia é incompatível, mesmo em causa própria, com cargos vinculados direta ou indiretamente a atividade policial de qualquer natureza. Incompatibilidade é proibição total."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Durante uma investigação, há indícios de que um advogado participou do crime. Pelo Estatuto da Advocacia, a busca no escritório dele", "opcoes": ["exige decisão judicial motivada e a presença de representante da OAB.", "é proibida em qualquer caso, pois o escritório é sempre inviolável.", "pode ser feita pela polícia, sem ordem judicial, em caso de urgência.", "exige apenas a autorização prévia e por escrito do presidente da OAB.", "pode alcançar todos os documentos de todos os clientes do escritório."], "gabarito": 0, "explicacao": "Art. 7º, § 6º: presentes indícios de autoria e materialidade de crime pelo advogado, o juiz pode decretar a quebra da inviolabilidade, em decisão motivada, com mandado específico e na presença de representante da OAB, vedado o uso de documentos de clientes não investigados."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Um preso, mantido incomunicável por decisão judicial, recebe a visita de um advogado que ainda não tem procuração. Pelo Estatuto da Advocacia, o advogado", "opcoes": ["não pode visitar o preso, pois a incomunicabilidade alcança a todos.", "pode comunicar-se com o cliente, pessoal e reservadamente.", "pode falar com o preso, mas na presença de um agente policial.", "só pode visitar o preso depois de juntar procuração aos autos.", "só pode visitar o preso com autorização do Ministério Público."], "gabarito": 1, "explicacao": "Art. 7º, III: é direito do advogado comunicar-se com seus clientes, pessoal e reservadamente, mesmo sem procuração, quando estiverem presos, detidos ou recolhidos, ainda que considerados incomunicáveis."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Pelo Estatuto da Advocacia, o advogado preso antes do trânsito em julgado da sentença condenatória tem direito", "opcoes": ["a cumprir prisão apenas em quartel das Forças Armadas.", "a cumprir a prisão em cela comum, mas separado dos condenados.", "a ser solto mediante simples requerimento da OAB, sem fiança.", "a permanecer preso na própria sede da seccional da OAB.", "a sala de Estado-Maior, ou, na falta dela, a prisão domiciliar."], "gabarito": 4, "explicacao": "Art. 7º, V: o advogado não pode ser recolhido preso, antes de sentença transitada em julgado, senão em sala de Estado-Maior, com instalações e comodidades condignas, e, na sua falta, em prisão domiciliar."}, {"materia": "pen", "texto_base": null, "enunciado": "Mário foi condenado definitivamente por um crime. Durante a execução da pena, entra em vigor lei que deixa de considerar aquele fato como crime. Nesse caso,", "opcoes": ["a lei nova só vale para fatos praticados depois de sua vigência.", "apenas a pena é reduzida, mantidos os demais efeitos penais.", "a pena continua, pois a condenação já havia transitado em julgado.", "extingue-se a punibilidade, mas permanecem os efeitos civis.", "extinguem-se a punibilidade e também o dever de indenizar a vítima."], "gabarito": 3, "explicacao": "É abolitio criminis (art. 2º e art. 107, III, do CP): cessam a execução e os efeitos penais da sentença, ainda que transitada em julgado. Os efeitos civis, como a obrigação de reparar o dano, permanecem."}, {"materia": "pen", "texto_base": null, "enunciado": "Um estrangeiro, no exterior, atenta contra a vida do Presidente da República do Brasil e é julgado e absolvido no país onde agiu. Quanto à lei penal brasileira,", "opcoes": ["aplica-se, mesmo com a absolvição no estrangeiro.", "aplica-se apenas se o autor entrar no território nacional.", "não se aplica, pois houve julgamento no exterior.", "aplica-se só se o fato também for crime no outro país.", "não se aplica, pois o autor é estrangeiro."], "gabarito": 0, "explicacao": "Art. 7º, I, 'a', e § 1º, do CP: crime contra a vida ou a liberdade do Presidente da República é caso de extraterritorialidade incondicionada. Aplica-se a lei brasileira ainda que o agente seja absolvido ou condenado no estrangeiro."}, {"materia": "pen", "texto_base": null, "enunciado": "Recém-chegado de uma região isolada, sem acesso a qualquer meio de informação, Tiago pratica conduta que, no Brasil, é crime, acreditando sinceramente que ela era permitida. Se o erro sobre a ilicitude for inevitável, Tiago", "opcoes": ["responderá normalmente, pois a lei é conhecida.", "terá a pena reduzida de 1/6 a 1/3.", "terá a conduta considerada atípica.", "ficará isento de pena, pelo erro inevitável.", "terá o dolo excluído, respondendo por culpa."], "gabarito": 3, "explicacao": "Art. 21 do CP: o erro sobre a ilicitude do fato (erro de proibição), se inevitável, isenta de pena; se evitável, diminui a pena de 1/6 a 1/3. Excluir o dolo é efeito do erro de tipo."}, {"materia": "pen", "texto_base": null, "enunciado": "Querendo matar dois desafetos que estavam lado a lado, Rui efetua um único disparo de fuzil, que atravessa e mata ambos. Quanto ao concurso de crimes,", "opcoes": ["há concurso formal próprio, com uma pena aumentada.", "há concurso formal impróprio, e as penas são somadas.", "há concurso material, por serem duas vítimas distintas.", "há crime único, pois houve uma só ação do agente.", "há crime continuado, com uma pena aumentada até 2/3."], "gabarito": 1, "explicacao": "Art. 70, parte final, do CP: com uma só ação, mas com desígnios autônomos em relação a cada resultado, o concurso formal é impróprio e as penas são aplicadas cumulativamente."}, {"materia": "pen", "texto_base": null, "enunciado": "Durante uma semana, Lia furta, todas as noites, mercadorias da mesma loja onde trabalha, sempre do mesmo modo. Presentes as condições de tempo, lugar e maneira de execução,", "opcoes": ["há crime único, pois a vítima foi sempre a mesma loja durante a semana.", "há crime continuado, com a pena de um só crime aumentada de 1/6 a 2/3.", "há concurso formal, com a pena de um só crime aumentada de 1/6 até a metade.", "há concurso material, com a soma das penas de todos os furtos praticados.", "há crime habitual, que só se consuma após a reiteração da conduta."], "gabarito": 1, "explicacao": "Art. 71 do CP: crimes da mesma espécie, com condições semelhantes de tempo, lugar e modo de execução, configuram crime continuado. Aplica-se a pena de um só, aumentada de 1/6 a 2/3."}, {"materia": "pen", "texto_base": null, "enunciado": "Um particular, sabendo que o amigo é servidor público, ajuda-o a desviar computadores da repartição em que este trabalha, dividindo o lucro. O particular responde por", "opcoes": ["furto qualificado, pois não é funcionário público e não pode responder por peculato.", "receptação, pois apenas recebeu parte do proveito obtido pelo servidor.", "peculato, pois a condição de funcionário é elementar e ele a conhecia.", "favorecimento real, pois auxiliou a tornar seguro o proveito do crime.", "apropriação indébita, pois os bens não estavam na sua posse direta."], "gabarito": 2, "explicacao": "Art. 30 do CP: as circunstâncias de caráter pessoal não se comunicam, salvo quando elementares do crime. Conhecendo a condição de funcionário do comparsa, o particular responde por peculato."}, {"materia": "pen", "texto_base": null, "enunciado": "Um homem de 22 anos mantém relação sexual com uma adolescente de 13 anos, que diz ter consentido e já ter tido outros relacionamentos. Segundo a lei e a jurisprudência do STJ,", "opcoes": ["há estupro simples, pois não houve violência física contra a vítima.", "há importunação sexual, crime de menor potencial ofensivo.", "não há crime se a família da adolescente aprovar o relacionamento.", "não há crime, pois houve consentimento expresso da adolescente.", "há estupro de vulnerável, sendo irrelevante o consentimento."], "gabarito": 4, "explicacao": "Art. 217-A do CP e Súmula 593 do STJ: o crime se configura com conjunção carnal ou ato libidinoso com menor de 14 anos, sendo irrelevantes o consentimento, a experiência sexual anterior ou a existência de relacionamento."}, {"materia": "pen", "texto_base": null, "enunciado": "Para aplicar um golpe, Davi falsifica um cheque e o usa para comprar uma moto, obtendo a vantagem. O documento não tem mais potencialidade lesiva. Segundo a Súmula 17 do STJ, Davi responde por", "opcoes": ["estelionato qualificado pelo uso de documento.", "falsificação e estelionato, em concurso material.", "estelionato, que absorve o falso.", "uso de documento falso e estelionato, somados.", "falsificação de documento público apenas."], "gabarito": 2, "explicacao": "Súmula 17 do STJ: quando o falso se exaure no estelionato, sem mais potencialidade lesiva, é por este absorvido."}, {"materia": "pen", "texto_base": null, "enunciado": "Um grupo tenta depor, por meio de violência e grave ameaça, o governo legitimamente constituído. Pelo Código Penal, com a redação da Lei 14.197/2021, essa conduta configura", "opcoes": ["interrupção do processo eleitoral.", "abolição violenta do Estado Democrático de Direito.", "golpe de Estado.", "atentado à soberania.", "sabotagem."], "gabarito": 2, "explicacao": "Art. 359-M do CP: tentar depor, por meio de violência ou grave ameaça, o governo legitimamente constituído. A abolição violenta (art. 359-L) é tentar abolir o Estado Democrático de Direito, impedindo ou restringindo o exercício dos Poderes."}, {"materia": "pen", "texto_base": null, "enunciado": "Réu não reincidente em crime doloso é condenado a 1 ano e 8 meses de detenção, e o juiz entende incabível a substituição por pena restritiva de direitos. Quanto à suspensão condicional da pena (sursis),", "opcoes": ["não é cabível, pois a pena supera 1 ano.", "é cabível, com período de prova de 2 a 4 anos.", "não é cabível, pois só vale para reclusão.", "é cabível apenas se o réu tiver mais de 70 anos.", "é cabível, com período de prova de 1 a 2 anos."], "gabarito": 1, "explicacao": "Art. 77 do CP: pena não superior a 2 anos, réu não reincidente em crime doloso e não indicada a substituição por restritiva de direitos. O período de prova é de 2 a 4 anos."}, {"materia": "ppen", "texto_base": null, "enunciado": "Segundo o art. 3º-A do Código de Processo Penal, incluído pela Lei 13.964/2019, o processo penal terá estrutura", "opcoes": ["acusatória, vedada a iniciativa do juiz na fase de investigação.", "inquisitiva na investigação e acusatória apenas na fase judicial.", "inquisitiva, com o juiz conduzindo a produção das provas iniciais.", "mista, cabendo ao juiz completar as provas do Ministério Público.", "acusatória, mas com o juiz autorizado a requisitar o inquérito."], "gabarito": 0, "explicacao": "Art. 3º-A do CPP: o processo penal terá estrutura acusatória, vedadas a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação."}, {"materia": "ppen", "texto_base": null, "enunciado": "No curso de um processo, entra em vigor lei processual penal que altera o procedimento. Quanto aos atos já praticados e aos atos futuros,", "opcoes": ["aplica-se sempre a lei mais favorável ao réu, ainda que processual.", "a lei nova retroage e anula os atos praticados pela lei anterior.", "a lei nova só vale para processos iniciados após sua vigência.", "o processo fica suspenso até que o tribunal defina a lei aplicável.", "a lei nova aplica-se desde logo, sem invalidar os atos já feitos."], "gabarito": 4, "explicacao": "Art. 2º do CPP (tempus regit actum): a lei processual penal aplica-se desde logo, sem prejuízo da validade dos atos realizados sob a vigência da lei anterior."}, {"materia": "ppen", "texto_base": null, "enunciado": "Uma vítima que mora em Curitiba transfere dinheiro via Pix para um golpista que mantém conta bancária em São Paulo. Pelo CPP, após a Lei 14.155/2021, a competência para o estelionato é definida", "opcoes": ["pela prevenção, entre todos os juízos.", "pelo local da agência do golpista.", "pelo local do domicílio da vítima.", "pela Justiça Federal, por envolver banco.", "pelo local em que o golpista mora."], "gabarito": 2, "explicacao": "Art. 70, § 4º, do CPP: no estelionato praticado mediante transferência de valores, como o Pix, a competência é do local do domicílio da vítima; havendo várias vítimas, firma-se pela prevenção."}, {"materia": "ppen", "texto_base": null, "enunciado": "Uma prova foi obtida a partir de uma interceptação ilegal, mas a polícia demonstra que chegaria ao mesmo elemento por uma investigação já em curso e sem relação com a interceptação. Pelo CPP, essa prova", "opcoes": ["deve ser desentranhada, mas pode ser usada pelo juiz.", "é admissível apenas para absolver, nunca para condenar.", "é inadmissível, por ser ilícita por derivação.", "é admissível somente com concordância da defesa.", "é admissível, por derivar de fonte independente."], "gabarito": 4, "explicacao": "Art. 157, §§ 1º e 2º, do CPP: são inadmissíveis as provas derivadas das ilícitas, salvo quando não evidenciado o nexo de causalidade ou quando puderem ser obtidas por fonte independente."}, {"materia": "ppen", "texto_base": null, "enunciado": "Em patrulhamento, policiais fazem busca pessoal em um homem apenas porque ele “demonstrou nervosismo” ao ver a viatura, sem nenhum outro elemento concreto. Segundo o entendimento do STJ, essa busca", "opcoes": ["é ilícita, pois a fundada suspeita exige elementos objetivos.", "é lícita, pois o nervosismo basta como fundada suspeita no flagrante.", "é ilícita apenas se nada de ilegal for encontrado com o abordado.", "é lícita, desde que feita durante o dia e em via pública.", "é lícita, pois a busca pessoal nunca depende de qualquer requisito."], "gabarito": 0, "explicacao": "Art. 244 do CPP: a busca pessoal sem mandado exige fundada suspeita de que a pessoa porta arma ou objetos de crime. O STJ exige elementos objetivos e concretos; impressões subjetivas, como nervosismo, não bastam."}, {"materia": "ppen", "texto_base": null, "enunciado": "Um réu primário responde por furto simples (pena de 1 a 4 anos) e não há qualquer outra hipótese legal. Quanto à prisão preventiva, ela", "opcoes": ["é cabível, pois o furto é crime doloso contra o patrimônio.", "é cabível, desde que requerida pelo Ministério Público.", "não é cabível, pois o furto é de menor potencial ofensivo.", "não é cabível, pois a pena máxima não supera 4 anos.", "é cabível, pois o juiz pode decretá-la de ofício no processo."], "gabarito": 3, "explicacao": "Art. 313, I, do CPP: a preventiva cabe em crimes dolosos com pena máxima superior a 4 anos, salvo reincidência em crime doloso, violência doméstica ou dúvida sobre a identidade. E o juiz não pode decretá-la de ofício (art. 311)."}, {"materia": "ppen", "texto_base": null, "enunciado": "Um homem é preso em flagrante por furto simples (pena de 1 a 4 anos). Quanto à fiança,", "opcoes": ["o delegado pode arbitrá-la para qualquer crime afiançável.", "o delegado pode arbitrá-la, pois a pena máxima é de 4 anos.", "o crime é inafiançável, por ser doloso contra o patrimônio.", "só o juiz pode arbitrá-la, após a audiência de custódia.", "a fiança só pode ser concedida a pedido do Ministério Público."], "gabarito": 1, "explicacao": "Art. 322 do CPP: a autoridade policial só pode conceder fiança nas infrações cuja pena privativa de liberdade máxima não seja superior a 4 anos. Nos demais casos, a fiança é requerida ao juiz."}, {"materia": "ppen", "texto_base": null, "enunciado": "Durante uma investigação de corrupção, descobre-se que o investigado comprou um apartamento com dinheiro desviado. A medida assecuratória adequada para garantir que esse imóvel não seja alienado é", "opcoes": ["o sequestro.", "a hipoteca legal.", "a busca e apreensão.", "o arresto.", "a fiança criminal."], "gabarito": 0, "explicacao": "Art. 125 do CPP: cabe o sequestro dos bens imóveis adquiridos com os proventos da infração. O arresto e a hipoteca legal recaem sobre bens lícitos do acusado, para garantir a reparação do dano."}, {"materia": "ppen", "texto_base": null, "enunciado": "Segundo a Súmula 523 do STF, no processo penal,", "opcoes": ["a falta ou a deficiência da defesa nunca anulam o processo penal.", "a falta de defesa anula; a deficiência anula só com prejuízo.", "a falta de defesa só anula o processo se o réu provar prejuízo.", "a nulidade por defesa deficiente pode ser declarada de ofício.", "a deficiência da defesa sempre gera nulidade absoluta do processo."], "gabarito": 1, "explicacao": "Súmula 523 do STF: no processo penal, a falta da defesa constitui nulidade absoluta, mas a sua deficiência só o anulará se houver prova de prejuízo para o réu."}, {"materia": "leg", "texto_base": null, "enunciado": "A recepção de um hotel exige o RG de um hóspede e informa que só o devolverá no check-out, dias depois. Pela Lei 5.553/1968, a retenção do documento de identificação", "opcoes": ["constitui apenas infração administrativa, sem repercussão penal.", "constitui crime de abuso de autoridade, de ação pública.", "é lícita por até 30 dias, desde que haja recibo de entrega.", "é lícita, se prevista no regulamento interno do estabelecimento.", "constitui contravenção penal, punida com prisão simples ou multa."], "gabarito": 4, "explicacao": "A Lei 5.553/1968 proíbe reter documento de identificação. Quem o exige deve extrair os dados em até 5 dias e devolvê-lo. A retenção é contravenção penal (art. 3º), punida com prisão simples de 1 a 3 meses ou multa."}, {"materia": "leg", "texto_base": null, "enunciado": "Sob influência de álcool, um motorista atropela e mata um pedestre, sem intenção de matar. Pelo Código de Trânsito Brasileiro, após a Lei 13.546/2017, a pena é de", "opcoes": ["reclusão, de 2 a 5 anos, com aumento de metade.", "detenção, de 6 meses a 3 anos, por ser crime culposo.", "detenção, de 2 a 4 anos, e suspensão ou proibição de dirigir.", "reclusão, de 6 a 20 anos, como no homicídio simples doloso.", "reclusão, de 5 a 8 anos, e suspensão ou proibição de dirigir."], "gabarito": 4, "explicacao": "Art. 302, § 3º, do CTB: homicídio culposo na direção sob influência de álcool ou outra substância psicoativa: reclusão de 5 a 8 anos, mais suspensão ou proibição de obter a habilitação."}, {"materia": "leg", "texto_base": null, "enunciado": "Um motorista causa um acidente com vítima e presta pronto e integral socorro a ela. Pelo Código de Trânsito Brasileiro,", "opcoes": ["ficará isento de responder pelo crime culposo de trânsito.", "será preso em flagrante, mas poderá pagar fiança na delegacia.", "não se imporá prisão em flagrante nem se exigirá fiança.", "terá a pena perdoada, desde que a vítima sobreviva ao acidente.", "só será preso se tiver ingerido qualquer bebida alcoólica."], "gabarito": 2, "explicacao": "Art. 301 do CTB: ao condutor que prestar pronto e integral socorro à vítima não se imporá prisão em flagrante, nem se exigirá fiança. Ele continua respondendo pelo crime, se houver."}, {"materia": "leg", "texto_base": null, "enunciado": "Uma empresa é denunciada por crime ambiental, mas não é possível identificar a pessoa física responsável pela decisão. Segundo o entendimento do STF, a responsabilização penal da pessoa jurídica", "opcoes": ["depende da denúncia conjunta de um dirigente da empresa.", "só é possível se a empresa for de grande porte.", "só é possível na esfera administrativa, não na penal.", "é possível, sem depender da punição de uma pessoa física.", "é inconstitucional, pois a pena é sempre pessoal."], "gabarito": 3, "explicacao": "O STF (RE 548.181) afastou a teoria da dupla imputação: a pessoa jurídica pode ser responsabilizada penalmente por crime ambiental (art. 225, § 3º, da CF e Lei 9.605/1998) independentemente da responsabilização de pessoa física."}, {"materia": "leg", "texto_base": null, "enunciado": "Um adolescente é apreendido em flagrante por ato infracional grave, e o juiz determina sua internação antes da sentença. Pelo ECA, essa internação provisória", "opcoes": ["pode durar até 3 anos.", "não pode passar de 10 dias.", "não pode passar de 90 dias.", "dura até a sentença, sem prazo.", "não pode passar de 45 dias."], "gabarito": 4, "explicacao": "Art. 108 do ECA: a internação, antes da sentença, pode ser determinada pelo prazo máximo de 45 dias, com decisão fundamentada."}, {"materia": "leg", "texto_base": null, "enunciado": "Um filho de 30 anos subtrai, sem violência, o dinheiro da aposentadoria do pai, de 72 anos, com quem mora. Quanto à imunidade penal entre parentes,", "opcoes": ["aplica-se, salvo se o filho for reincidente em furto.", "não se aplica apenas se o valor subtraído for elevado.", "aplica-se, mas a ação depende de representação do pai.", "não se aplica, porque a vítima tem 60 anos ou mais.", "aplica-se, e o filho fica isento de pena por ser descendente."], "gabarito": 3, "explicacao": "Art. 183, III, do CP e art. 95 do Estatuto da Pessoa Idosa: a imunidade dos arts. 181 e 182 do CP não se aplica quando a vítima tem 60 anos ou mais. A ação é pública incondicionada."}, {"materia": "leg", "texto_base": null, "enunciado": "Sobre a Lei de Lavagem de Dinheiro (Lei 9.613/1998), após a Lei 12.683/2012, é correto afirmar que", "opcoes": ["só os crimes da lista fechada da lei podem ser antecedentes.", "qualquer infração penal pode ser antecedente da lavagem.", "a condenação pela infração antecedente é exigida antes.", "a lavagem só se configura com valores acima de 100 mil reais.", "o autor do crime antecedente não pode responder por lavagem."], "gabarito": 1, "explicacao": "Desde a Lei 12.683/2012, não há mais rol de crimes antecedentes: qualquer infração penal pode ser antecedente. O processo da lavagem independe do processo e julgamento da infração antecedente (art. 2º, II)."}, {"materia": "leg", "texto_base": null, "enunciado": "Pela Lei 12.830/2013, que trata da investigação criminal conduzida pelo delegado de polícia, o indiciamento", "opcoes": ["dispensa fundamentação, por ser ato discricionário.", "pode ser feito pelo MP ou pelo juiz, de ofício.", "é ato do escrivão, a pedido do investigado.", "é privativo do delegado, por ato fundamentado.", "só ocorre depois do oferecimento da denúncia."], "gabarito": 3, "explicacao": "Art. 2º, § 6º, da Lei 12.830/2013: o indiciamento, privativo do delegado de polícia, dar-se-á por ato fundamentado, mediante análise técnico-jurídica do fato, com indicação da autoria, materialidade e circunstâncias."}, {"materia": "leg", "texto_base": null, "enunciado": "Um condenado em regime fechado trabalha regularmente durante 90 dias. Pela Lei de Execução Penal, ele poderá remir", "opcoes": ["30 dias de pena.", "15 dias de pena.", "45 dias de pena.", "60 dias de pena.", "90 dias de pena."], "gabarito": 0, "explicacao": "Art. 126, § 1º, II, da LEP: 1 dia de pena a cada 3 dias de trabalho. 90 ÷ 3 = 30. Pelo estudo, a remição é de 1 dia a cada 12 horas de frequência escolar."}, {"materia": "cont", "texto_base": null, "enunciado": "Na conciliação bancária de uma empresa, o extrato mostra saldo de R$ 12.000,00. Há cheques emitidos e ainda não compensados de R$ 2.000,00, e uma tarifa bancária de R$ 50,00 debitada pelo banco que a empresa não registrou. O saldo contábil da empresa é de R$ 10.050,00. O saldo correto, após os ajustes, é de", "opcoes": ["R$ 10.000,00.", "R$ 14.000,00.", "R$ 9.950,00.", "R$ 10.050,00.", "R$ 12.000,00."], "gabarito": 0, "explicacao": "Banco: 12.000 − 2.000 (cheques não compensados) = 10.000. Empresa: 10.050 − 50 (tarifa não lançada) = 10.000. Os dois lados batem em R$ 10.000,00."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma duplicata de R$ 10.000,00 é descontada em um banco 3 meses antes do vencimento, com desconto comercial simples à taxa de 2% ao mês. O valor líquido recebido pela empresa é de", "opcoes": ["R$ 9.433,96.", "R$ 9.600,00.", "R$ 9.800,00.", "R$ 9.400,00.", "R$ 10.600,00."], "gabarito": 3, "explicacao": "Desconto comercial (por fora) = 10.000 × 0,02 × 3 = 600. Valor líquido = 10.000 − 600 = 9.400. R$ 9.433,96 seria o resultado do desconto racional (por dentro)."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma aplicação de R$ 10.000,00 rende juros compostos de 10% ao mês. Ao final de 3 meses, o montante será de", "opcoes": ["R$ 13.000,00.", "R$ 12.100,00.", "R$ 13.100,00.", "R$ 13.310,00.", "R$ 13.331,00."], "gabarito": 3, "explicacao": "M = 10.000 × 1,1³ = 10.000 × 1,331 = 13.310. Em juros simples, seriam 13.000."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma taxa de juros compostos de 1% ao mês é equivalente, em um ano, a aproximadamente", "opcoes": ["12,68% ao ano.", "11,36% ao ano.", "12,36% ao ano.", "12,00% ao ano.", "13,00% ao ano."], "gabarito": 0, "explicacao": "Taxa equivalente: (1,01)¹² − 1 ≈ 0,1268, ou 12,68% ao ano. Os 12% seriam a taxa proporcional, válida em juros simples."}, {"materia": "cont", "texto_base": null, "enunciado": "Em dezembro de 2026, uma empresa recebe antecipadamente o aluguel de janeiro a março de 2027 de um imóvel que aluga a terceiros. Pelo regime de competência, em dezembro esse valor deve ser registrado como", "opcoes": ["receita de dezembro, pois o dinheiro já entrou.", "patrimônio líquido, como reserva de lucros.", "passivo, pois a receita ainda não foi ganha.", "ativo, pois é um direito a receber da empresa.", "despesa antecipada, no ativo circulante."], "gabarito": 2, "explicacao": "O recebimento antecipado gera uma obrigação de prestar o serviço (receita diferida ou adiantamento), registrada no passivo. A receita é reconhecida mês a mês, de janeiro a março."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa apresentou: receita bruta de R$ 200.000,00, devoluções de R$ 10.000,00, ICMS sobre vendas de R$ 30.000,00, CMV de R$ 90.000,00, despesas administrativas de R$ 25.000,00 e despesas com vendas de R$ 15.000,00. O resultado operacional foi de", "opcoes": ["R$ 30.000,00.", "R$ 60.000,00.", "R$ 40.000,00.", "R$ 70.000,00.", "R$ 20.000,00."], "gabarito": 0, "explicacao": "Receita líquida = 200.000 − 10.000 − 30.000 = 160.000. Lucro bruto = 160.000 − 90.000 = 70.000. Resultado operacional = 70.000 − 25.000 − 15.000 = 30.000."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa tem ativo circulante de R$ 300.000,00, passivo circulante de R$ 180.000,00 e passivo não circulante de R$ 70.000,00. O capital circulante líquido é de", "opcoes": ["R$ 480.000,00.", "R$ 50.000,00.", "R$ 230.000,00.", "R$ 250.000,00.", "R$ 120.000,00."], "gabarito": 4, "explicacao": "Capital circulante líquido = ativo circulante − passivo circulante = 300.000 − 180.000 = 120.000. O passivo não circulante não entra nesse cálculo."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma máquina com custo de R$ 50.000,00 e depreciação acumulada de R$ 30.000,00 é vendida à vista por R$ 25.000,00. Na baixa do bem, a empresa apura", "opcoes": ["perda de capital de R$ 5.000,00.", "ganho de capital de R$ 5.000,00.", "ganho de capital de R$ 25.000,00.", "ganho de capital de R$ 20.000,00.", "perda de capital de R$ 25.000,00."], "gabarito": 1, "explicacao": "Valor contábil = 50.000 − 30.000 = 20.000. Venda por 25.000: ganho de 25.000 − 20.000 = 5.000."}, {"materia": "const", "texto_base": null, "enunciado": "O irmão do governador de um estado, no curso do mandato deste, quer se candidatar a deputado estadual nesse mesmo estado, sem nunca ter exercido mandato. Pela Constituição, ele é", "opcoes": ["inelegível, por ser parente de 2º grau do governador.", "inelegível apenas se o governador disputar a reeleição.", "elegível, desde que se filie a partido diferente do governador.", "elegível, pois o cargo de deputado é do Poder Legislativo.", "elegível, pois a inelegibilidade alcança só cônjuge e filhos."], "gabarito": 0, "explicacao": "Art. 14, § 7º, da CF: são inelegíveis, no território de jurisdição do titular, o cônjuge e os parentes até o 2º grau do governador, salvo se já titulares de mandato eletivo e candidatos à reeleição. Irmão é parente colateral de 2º grau."}, {"materia": "const", "texto_base": null, "enunciado": "Um grupo de moradores quer criar um partido político que atue apenas no seu estado e receba doações de uma fundação estrangeira. Pela Constituição,", "opcoes": ["pode, desde que registre o estatuto no Tribunal Regional Eleitoral do próprio estado.", "pode receber recursos estrangeiros, mas deve ter caráter nacional desde a criação.", "pode atuar só no estado, mas não pode receber recursos de entidade estrangeira.", "pode, desde que a fundação estrangeira tenha sede de representação no Brasil.", "não pode: o partido deve ser nacional e não pode receber recurso estrangeiro."], "gabarito": 4, "explicacao": "Art. 17, I e II, da CF: os partidos devem ter caráter nacional e é proibido receber recursos financeiros de entidade ou governo estrangeiros."}, {"materia": "const", "texto_base": null, "enunciado": "Um grupo pretende fazer uma manifestação pacífica, sem armas, em uma praça pública. Pela Constituição, a reunião", "opcoes": ["depende de autorização prévia da autoridade policial competente.", "independe de autorização, exigindo apenas aviso prévio à autoridade.", "independe de aviso, podendo frustrar outra reunião já convocada.", "só pode ocorrer em locais fechados, para evitar riscos à ordem.", "depende de autorização judicial, se reunir mais de cem pessoas."], "gabarito": 1, "explicacao": "Art. 5º, XVI, da CF: todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso."}, {"materia": "const", "texto_base": null, "enunciado": "Uma associação civil passa a ser investigada por atividades ilícitas. Pela Constituição, a sua dissolução compulsória", "opcoes": ["pode ser feita por ato do Poder Executivo.", "exige apenas decisão judicial liminar.", "exige decisão judicial transitada em julgado.", "depende de lei específica para cada associação.", "pode ser determinada pela autoridade policial."], "gabarito": 2, "explicacao": "Art. 5º, XIX, da CF: as associações só podem ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado."}, {"materia": "const", "texto_base": null, "enunciado": "A Assembleia Legislativa de um estado aprova lei que cria um novo crime e define sua pena. Essa lei é", "opcoes": ["constitucional, pois a matéria penal é de competência concorrente.", "inconstitucional apenas se a pena prevista for de reclusão.", "constitucional, se o crime for de interesse local do estado.", "constitucional, se sancionada pelo governador do estado.", "inconstitucional: direito penal é matéria privativa da União."], "gabarito": 4, "explicacao": "Art. 22, I, da CF: compete privativamente à União legislar sobre direito penal e processual. Lei complementar federal pode autorizar os estados a legislar sobre questões específicas (parágrafo único), o que não ocorreu."}, {"materia": "const", "texto_base": null, "enunciado": "Pela Constituição, à Polícia Federal cabe, entre outras funções,", "opcoes": ["apurar todas as infrações penais praticadas contra servidores estaduais.", "prevenir e reprimir o tráfico ilícito de entorpecentes e drogas afins.", "fazer o policiamento ostensivo nas rodovias federais de todo o país.", "exercer a polícia judiciária dos estados nos crimes contra a vida.", "fazer a segurança dos estabelecimentos penais estaduais e distritais."], "gabarito": 1, "explicacao": "Art. 144, § 1º, II, da CF. O patrulhamento ostensivo das rodovias federais é da PRF, a polícia judiciária dos estados é das polícias civis e a segurança dos presídios é das polícias penais."}, {"materia": "const", "texto_base": null, "enunciado": "Uma brasileira nata, que mora em Portugal, adquire voluntariamente a nacionalidade portuguesa. Pela Constituição, com a redação da EC 131/2023, ela", "opcoes": ["perde automaticamente a nacionalidade brasileira ao naturalizar-se.", "perde a nacionalidade, mas pode readquiri-la após cinco anos.", "torna-se brasileira naturalizada a partir da nova nacionalidade.", "perde a nacionalidade, salvo se a outra for originária.", "não perde a nacionalidade brasileira, salvo se pedir expressamente."], "gabarito": 4, "explicacao": "Após a EC 131/2023, o brasileiro só perde a nacionalidade por cancelamento da naturalização (por fraude ou atentado contra a ordem constitucional) ou por pedido expresso, ressalvadas situações de apatridia (art. 12, § 4º)."}, {"materia": "const", "texto_base": null, "enunciado": "Um servidor público estável tem o seu cargo extinto por lei. Pela Constituição, ele", "opcoes": ["fica em disponibilidade, com remuneração proporcional ao tempo de serviço.", "é exonerado de ofício, com indenização de um mês por ano de serviço.", "é demitido, podendo recorrer da decisão na esfera administrativa.", "fica em disponibilidade, com remuneração integral até o aproveitamento.", "é aposentado compulsoriamente, com proventos integrais e paridade."], "gabarito": 0, "explicacao": "Art. 41, § 3º, da CF: extinto o cargo ou declarada a sua desnecessidade, o servidor estável ficará em disponibilidade, com remuneração proporcional ao tempo de serviço, até seu adequado aproveitamento em outro cargo."}, {"materia": "adm", "texto_base": null, "enunciado": "A prefeitura concedeu a um particular, que cumpriu todos os requisitos legais, licença para construir. Meses depois, por mudança de prioridades, quer revogar essa licença. Essa revogação é", "opcoes": ["incabível apenas se a obra já estiver totalmente concluída.", "incabível, pois a licença é ato vinculado e já gerou direito.", "cabível, desde que com efeitos retroativos à data da concessão.", "cabível a qualquer tempo, por conveniência e oportunidade.", "cabível somente pelo Poder Judiciário, a pedido da prefeitura."], "gabarito": 1, "explicacao": "A revogação incide sobre atos discricionários e não alcança atos vinculados, nem os que geraram direitos adquiridos. A licença é ato vinculado. Havendo interesse público superveniente, cabe desapropriação do direito, com indenização."}, {"materia": "adm", "texto_base": null, "enunciado": "Um ato administrativo foi praticado com desvio de finalidade: a autoridade removeu um servidor apenas para puni-lo. Quanto à convalidação, esse ato", "opcoes": ["deve ser revogado, com efeitos a partir da revogação.", "pode ser convalidado pela própria autoridade, se houver motivo.", "não pode ser convalidado e deve ser anulado pela administração.", "convalida-se sozinho após 1 ano, se não houver recurso.", "pode ser convalidado por autoridade superior, com efeitos retroativos."], "gabarito": 2, "explicacao": "Admite-se convalidar vícios sanáveis de competência (não exclusiva) e de forma (não essencial). Vícios de finalidade, motivo e objeto são insanáveis: o ato deve ser anulado."}, {"materia": "adm", "texto_base": null, "enunciado": "O Presidente da República extingue, por decreto, cargos públicos que estavam vagos. Esse decreto", "opcoes": ["é válido, mas apenas se os cargos forem de livre nomeação.", "é inválido, pois a extinção de cargos sempre exige lei específica.", "é inválido, pois o decreto só serve para regulamentar leis.", "é válido, pois a Constituição admite o decreto autônomo nesse caso.", "é válido, desde que o Congresso o aprove em até 60 dias."], "gabarito": 3, "explicacao": "Art. 84, VI, 'b', da CF: compete ao Presidente dispor, mediante decreto, sobre a extinção de funções ou cargos públicos, quando vagos. É um dos casos de decreto autônomo."}, {"materia": "adm", "texto_base": null, "enunciado": "Um órgão público quer contratar uma agência de publicidade, sem licitação, alegando notória especialização. Pela Lei 14.133/2021, essa contratação direta é", "opcoes": ["permitida, por ser serviço técnico de natureza intelectual.", "permitida por dispensa, se o valor for inferior a R$ 100 mil.", "vedada, pois a lei proíbe a inexigibilidade para publicidade.", "permitida, desde que a agência tenha notória especialização.", "vedada apenas se houver mais de três agências na cidade."], "gabarito": 2, "explicacao": "Art. 74, III, da Lei 14.133/2021: é inexigível a contratação de serviços técnicos especializados de natureza predominantemente intelectual com profissionais ou empresas de notória especialização, vedada a inexigibilidade para serviços de publicidade e divulgação."}, {"materia": "adm", "texto_base": null, "enunciado": "Ao fiscalizar um contrato administrativo do Executivo federal, o TCU constata ilegalidade. Pela Constituição, a sustação desse contrato", "opcoes": ["é feita diretamente pelo TCU, de imediato.", "é determinada pelo Ministério Público.", "depende de decisão do Supremo Tribunal Federal.", "é decidida pelo Presidente da República.", "é adotada diretamente pelo Congresso Nacional."], "gabarito": 4, "explicacao": "Art. 71, § 1º, da CF: no caso de contrato, o ato de sustação será adotado diretamente pelo Congresso Nacional, que solicitará ao Executivo as medidas cabíveis. Se em 90 dias nada for feito, o TCU decide (§ 2º). Atos administrativos o TCU pode sustar diretamente."}, {"materia": "adm", "texto_base": null, "enunciado": "Um detento é morto por outros presos dentro de uma cadeia pública, sem que os agentes tivessem agido para evitar. Segundo o STF, a responsabilidade do Estado", "opcoes": ["é solidária entre o Estado e os presos que praticaram o homicídio.", "é objetiva, pela violação do dever específico de proteção do preso.", "é subjetiva, exigindo prova de culpa individual de um agente.", "existe apenas se a família provar a omissão do diretor da unidade.", "não existe, pois a morte foi causada por terceiros, os outros presos."], "gabarito": 1, "explicacao": "STF, Tema 592 (RE 841.526): em caso de inobservância do dever específico de proteção previsto no art. 5º, XLIX, da CF, o Estado é responsável pela morte de detento."}, {"materia": "adm", "texto_base": null, "enunciado": "Após a Lei 14.230/2021, nos atos de improbidade que importam enriquecimento ilícito, a suspensão dos direitos políticos pode chegar a até", "opcoes": ["8 anos.", "10 anos.", "14 anos.", "20 anos.", "5 anos."], "gabarito": 2, "explicacao": "Art. 12, I, da Lei 8.429/1992: no enriquecimento ilícito, a suspensão dos direitos políticos vai até 14 anos; na lesão ao erário, até 12 anos. Para os atos contra princípios, não há mais suspensão de direitos políticos."}, {"materia": "adm", "texto_base": null, "enunciado": "Um delegado aplica a um investigador uma pena de suspensão de 60 dias, embora a lei atribua essa penalidade, acima de 30 dias, a autoridade superior. Essa conduta caracteriza", "opcoes": ["omissão administrativa, sem nulidade.", "abuso de forma, vício sanável sempre.", "excesso de poder, vício de competência.", "poder de polícia, exercido regularmente.", "desvio de finalidade, vício de motivo."], "gabarito": 2, "explicacao": "Há abuso de poder na modalidade excesso: o agente atua além de sua competência. No desvio de finalidade, o agente é competente, mas busca fim diverso do previsto em lei."}, {"materia": "est", "texto_base": null, "enunciado": "Em uma distribuição de dados, a média é maior que a mediana, que é maior que a moda. Essa distribuição é", "opcoes": ["assimétrica negativa, ou à esquerda.", "assimétrica positiva, ou à direita.", "bimodal, sem assimetria.", "simétrica e mesocúrtica.", "simétrica e platicúrtica."], "gabarito": 1, "explicacao": "Quando média > mediana > moda, a cauda longa fica à direita: assimetria positiva. Na negativa, a ordem se inverte (média < mediana < moda)."}, {"materia": "est", "texto_base": null, "enunciado": "Uma distribuição de frequências é mais achatada que a curva normal, com valores mais espalhados em torno da média. Quanto à curtose, ela é", "opcoes": ["assimétrica positiva.", "leptocúrtica.", "platicúrtica.", "mesocúrtica.", "assimétrica negativa."], "gabarito": 2, "explicacao": "Platicúrtica: mais achatada que a normal. Leptocúrtica: mais alongada (pico mais alto). Mesocúrtica: semelhante à normal."}, {"materia": "est", "texto_base": null, "enunciado": "Para estimar a opinião dos servidores de uma secretaria, um pesquisador divide os servidores por setor e sorteia, dentro de cada setor, um número de pessoas proporcional ao seu tamanho. Essa técnica é a amostragem", "opcoes": ["estratificada.", "por conglomerados.", "sistemática.", "aleatória simples.", "por conveniência."], "gabarito": 0, "explicacao": "Na estratificada, a população é dividida em estratos (subgrupos) e se sorteia dentro de cada um. Na por conglomerados, sorteiam-se grupos inteiros e todos os seus elementos são pesquisados."}, {"materia": "est", "texto_base": null, "enunciado": "De uma lista de 1.000 boletins de ocorrência, deseja-se retirar uma amostra sistemática de 50. Sorteia-se um número inicial e, a partir dele, toma-se um boletim a cada", "opcoes": ["25 posições.", "100 posições.", "20 posições.", "50 posições.", "10 posições."], "gabarito": 2, "explicacao": "Intervalo de amostragem = N ÷ n = 1.000 ÷ 50 = 20. Sorteia-se o início entre 1 e 20 e toma-se a cada 20 posições."}, {"materia": "est", "texto_base": null, "enunciado": "Em uma fiscalização, 2% dos veículos têm irregularidade. Um equipamento acusa corretamente 90% dos irregulares, mas também acusa, por erro, 10% dos regulares. Se o equipamento acusou um veículo, a probabilidade de ele ser realmente irregular é de aproximadamente", "opcoes": ["15,5%.", "90%.", "50%.", "2%.", "18%."], "gabarito": 0, "explicacao": "Teorema de Bayes: P(acusa) = 0,02 × 0,9 + 0,98 × 0,1 = 0,018 + 0,098 = 0,116. P(irregular | acusa) = 0,018 ÷ 0,116 ≈ 0,155, ou 15,5%."}, {"materia": "est", "texto_base": null, "enunciado": "Os eventos A e B são independentes, com P(A) = 0,3 e P(B) = 0,4. A probabilidade de ocorrer A ou B é", "opcoes": ["0,46.", "0,12.", "0,70.", "0,82.", "0,58."], "gabarito": 4, "explicacao": "P(A ∩ B) = 0,3 × 0,4 = 0,12. P(A ∪ B) = 0,3 + 0,4 − 0,12 = 0,58."}, {"materia": "est", "texto_base": null, "enunciado": "Uma turma A, com 20 alunos, teve média 7,0 em uma prova, e uma turma B, com 30 alunos, teve média 8,0. A média geral dos 50 alunos é", "opcoes": ["8,0.", "7,6.", "7,4.", "7,5.", "7,8."], "gabarito": 1, "explicacao": "Média ponderada: (20 × 7 + 30 × 8) ÷ 50 = (140 + 240) ÷ 50 = 380 ÷ 50 = 7,6."}, {"materia": "est", "texto_base": null, "enunciado": "Uma amostra de três observações tem os valores 3, 5 e 7. O desvio-padrão amostral desses dados é", "opcoes": ["4.", "2,67.", "5.", "2.", "1,63."], "gabarito": 3, "explicacao": "Média = 5. Soma dos quadrados dos desvios = 4 + 0 + 4 = 8. Variância amostral = 8 ÷ (3 − 1) = 4; desvio-padrão = 2. O populacional seria √(8/3) ≈ 1,63."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('policial', date '2026-11-08', 'Simulado 3 · Policial', 'AOCP', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'policial' and s.data = date '2026-11-08' group by s.id;
